export const days = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

export const hours = ["9am", "11am", "1pm", "3pm", "5pm", "7pm"];

export const orders = days.flatMap((day, dayIndex) =>
  hours.map((hour, hourIndex) => ({
    day,
    hour,
    orders: Math.round(
      20 + 30 * Math.sin((hourIndex + 1) / 2) + (dayIndex < 5 ? 15 : -10) + ((dayIndex * 7) % 11),
    ),
  })),
);

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { HeatmapChart } from "@/registry/erbium/charts/heatmap-chart";

import PlaygroundExample from "./variants/playground";

const PlaygroundSource = "import { HeatmapChart } from \"@/registry/erbium/charts/heatmap-chart\";\nimport { days, hours, orders } from \"../examples/data\";\n\nconst Example = (args: { legend: boolean; tooltip: boolean }) => (\n  <div className=\"w-2xl max-w-full p-4\">\n    <HeatmapChart\n      ariaLabel=\"Orders by weekday and hour\"\n      data={orders}\n      x=\"hour\"\n      y=\"day\"\n      value=\"orders\"\n      columns={hours}\n      rows={days}\n      initialWidth={640}\n      {...args}\n    />\n  </div>\n);\n\nexport default Example;\n";

const meta = {
  component: HeatmapChart,
  parameters: {
    docs: {
      description: {
        component: "## Usage\n\nPass one row per cell, and name the column, row, and value fields with `x`, `y`, and `value`.\n\n```tsx\nimport { HeatmapChart } from \"@/registry/erbium/charts/heatmap-chart\";\n\n<HeatmapChart\n  ariaLabel=\"Orders by weekday and hour\"\n  data={orders}\n  x=\"hour\"\n  y=\"day\"\n  value=\"orders\"\n/>;\n```\n\nCells are one color at five strengths, mixed into the page background rather than interpolated, so they follow light and dark themes. `color` changes the base color; `columns` and `rows` fix the order of each axis. With only a few values, use a table or a [Bar Chart](/docs/charts/bar-chart).",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof HeatmapChart>;

export default { ...meta, title: "Charts/Heatmap",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

export const Playground: StoryObj<{ legend: boolean; tooltip: boolean }> = {
  argTypes: { legend: { control: "boolean" }, tooltip: { control: "boolean" } },
  args: { legend: true, tooltip: true },
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

import { HeatmapChart } from "@/registry/erbium/charts/heatmap-chart";
import { days, hours, orders } from "../examples/data";

const Example = (args: { legend: boolean; tooltip: boolean }) => (
  <div className="w-2xl max-w-full p-4">
    <HeatmapChart
      ariaLabel="Orders by weekday and hour"
      data={orders}
      x="hour"
      y="day"
      value="orders"
      columns={hours}
      rows={days}
      initialWidth={640}
      {...args}
    />
  </div>
);

export default Example;

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </SkeletonProvider>
  </CSPProvider>
);

export const ShowcaseSurface = ({ children }: { children?: ReactNode }) => (
  <div
    data-slot="component-preview"
    className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
  >
    {children}
  </div>
);
